import{_ as o,o as a,c as r,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"O que é o Orbit","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/index.md","filePath":"pt-BR/guide/index.md"}'),t={name:"pt-BR/guide/index.md"};function s(d,e,n,u,l,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="o-que-e-o-orbit" tabindex="-1">O que é o Orbit <a class="header-anchor" href="#o-que-e-o-orbit" aria-label="Permalink to &quot;O que é o Orbit&quot;">​</a></h1><p>O Orbit é uma plataforma que você instala nos seus próprios servidores. Ele transforma uma máquina Linux limpa num lugar para rodar aplicações e bancos de dados, e te dá um console para isso, sem escrever manifests de Kubernetes nem scripts de shell.</p><h2 id="o-que-roda-onde" tabindex="-1">O que roda onde <a class="header-anchor" href="#o-que-roda-onde" aria-label="Permalink to &quot;O que roda onde&quot;">​</a></h2><ul><li><strong>O servidor principal:</strong> onde você roda o instalador. Ele guarda o plano de controle do Orbit (a API, o console e o banco de dados do próprio Orbit), o Kubernetes (<a href="https://k3s.io" target="_blank" rel="noreferrer">K3s</a>), o roteador Traefik que recebe o seu tráfego, o cert-manager para os certificados do Let&#39;s Encrypt e o BuildKit, que faz o build dos seus repositórios.</li><li><strong>Mais servidores:</strong> você pode adicionar servidores pelo console. Eles entram no mesmo cluster e rodam os serviços que você colocar neles.</li><li><strong>Suas aplicações e bancos:</strong> rodam como workloads do Kubernetes. Continuam atendendo enquanto o próprio Orbit reinicia ou se atualiza.</li></ul><h2 id="como-o-orbit-trabalha-com-voce" tabindex="-1">Como o Orbit trabalha com você <a class="header-anchor" href="#como-o-orbit-trabalha-com-voce" aria-label="Permalink to &quot;Como o Orbit trabalha com você&quot;">​</a></h2><ul><li><strong>Toda mudança é uma operação.</strong> Deploy, restore, mudança de recursos ou atualização rodam como uma operação com etapas, log e um resultado claro. Se o Orbit reiniciar no meio, a operação continua ou falha dizendo o motivo.</li><li><strong>Prévia antes de mudar.</strong> Mudar recursos, réplicas ou o runtime de um banco mostra antes o que isso reserva em cada servidor, como a mudança é aplicada e o que observar. Uma mudança que não cabe é bloqueada.</li><li><strong>O que você vê é o que foi observado.</strong> Os status vêm dos agentes dos servidores e do Kubernetes. Quando o Orbit fica um tempo sem notícias de um servidor, ele diz isso em vez de mostrar um status velho.</li><li><strong>Os limites são ditos.</strong> Cada tela diz o que um recurso não cobre. <a href="./limits">O que o Orbit não promete</a> reúne tudo num lugar só.</li></ul><h2 id="por-onde-comecar" tabindex="-1">Por onde começar <a class="header-anchor" href="#por-onde-comecar" aria-label="Permalink to &quot;Por onde começar&quot;">​</a></h2><ol><li><a href="./install">Instale o Orbit</a> num servidor.</li><li>Crie um <a href="./projects">projeto</a> e publique uma <a href="./applications">aplicação</a> a partir do <a href="./github">GitHub</a>, do <a href="./gitlab">GitLab</a>, do <a href="./bitbucket">Bitbucket</a> ou de uma imagem.</li><li>Adicione um <a href="./databases">banco de dados</a> e configure os <a href="./backups">backups</a> dele.</li><li>Leia <a href="./operating">Operando o Orbit</a> e <a href="./updates">Atualizações</a> antes de depender dele.</li></ol>',8)])])}const b=o(t,[["render",s]]);export{p as __pageData,b as default};
